pub fn set_name(for_me: bool, len: u32, same: bool, last_write: Option<u64>, now: u64) -> SetName {
    if !for_me || len > MAX_NAME_LEN {
        return SetName::Ignore;
    }
    if same {
        return SetName::Announce;
    }
    match last_write {
        Some(t) if now.saturating_sub(t) < MIN_WRITE_INTERVAL_MS => SetName::Announce,
        _ => SetName::Store,
    }
}

